// words: exact exact
// input: u32
// output: u32
// block: 64 1 1
// overflow checks: on
// cooperative
#![cfg_attr(not(cpu_reference), no_std)]
#![allow(unused_mut, unused_variables, unused_assignments, unused_parens, unused_labels, unused_braces, unused_comparisons, unused_imports, dead_code, unreachable_code, arithmetic_overflow, unconditional_panic)]

#[derive(Clone, Copy)]
enum E0 { V0, V1 }

fn cooperate(input: u32, lane: u32, a12: AtomicThreadgroupBuffer<i32, 2>) -> [u32; 3] {
    let mut l13: bool = unsafe { simdgroup::any(true) };
    let mut l14: bool = unsafe { simdgroup::any(true) };
    let mut l15: bool = unsafe { simdgroup::all((l14 || (if (l13 && l13) { true } else { matches!(E0::V1, E0::V1) }))) };
    [0_u32, 0_u32, 0_u32]
}

fn run(input: u32, k0: u32, k1: u32, k2: u32) -> [u32; 2] {
    [0_u32, 0_u32]
}

#[cfg(not(cpu_reference))]
use metal_oxide_device::{AtomicBuffer, AtomicThreadgroupBuffer, ReadBuffer, ThreadgroupBuffer, WriteBuffer, block_idx, kernel, simdgroup, thread_idx, threadgroup};

#[cfg(not(cpu_reference))]
#[kernel(block = (64, 1, 1))]
pub unsafe fn generated(input: ReadBuffer<u32>, output: WriteBuffer<u32>, n: u32) {
    let i = block_idx().x * 64 + thread_idx().x;
    let value = if i < n { unsafe { input.load_unchecked(i) } } else { 0 };
    let a12 = threadgroup::shared_atomic::<i32, 2>();
    let k = cooperate(value, thread_idx().x, a12);
    if i < n {
        let words = run(value, k[0], k[1], k[2]);
        unsafe {
        output.store_unchecked(i * 2 + 0, words[0]);
        output.store_unchecked(i * 2 + 1, words[1]);
        }
    }
}

